/**
 * Filmernas texter som hjälpkälla (2026-11-21, beslut F8): the spoken Swedish sentences and scene titles of the product's own
 * film manuscripts, in plain text, for the rule-based help search (lib/help/help-search.ts). Only the voice: no picture or click
 * notes, no pronunciation or recording notes. The demo's invented people and companies are taken out (the film's main person
 * reads "du", everyone else "en kollega", the companies "företaget" and "kunden"), so a help answer never names another
 * company. Sentences about the film itself, the demo, the closing line and outside addresses are left out.
 *
 * `recorded` films are published on the public film page; the others are manuscripts not recorded yet (help text only, no link).
 * `page` is the app page the film is about. Copyright precaution: the owner's own text only, nothing from standards or manuals.
 * Made again from the manuscripts by hand when a film changes; tests/help-search.test.ts checks that no demo name is left.
 */
export type FilmText = {
  key: string;
  /** The film's number in the series (0 is the one-minute overview). */
  number: number;
  title: string;
  subtitle: string;
  recorded: boolean;
  page: string;
  /** [scene title ("" when the manuscript has none), what the voice says]. */
  scenes: [string, string][];
};

